:root {
  --ink: #06100c;
  --panel: rgba(7, 19, 15, 0.78);
  --panel-strong: rgba(6, 16, 13, 0.94);
  --line: rgba(142, 255, 175, 0.2);
  --line-hot: rgba(144, 255, 159, 0.55);
  --green: #7dff5a;
  --green-soft: #baff9d;
  --yellow: #f5d33f;
  --red: #ff5c6c;
  --cyan: #6cecff;
  --text: #d9ede2;
  --muted: #7f9c8f;
  --font-display: "Bangers", Impact, sans-serif;
  --font-ui: "Rajdhani", "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #050a08;
  color: var(--text);
  font-family: var(--font-ui);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { position: fixed; inset: 0; }

button { font: inherit; }

#app {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at 50% 45%, #14271e 0%, #07100d 48%, #030605 100%);
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

#ui {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  opacity: 0;
  transition: opacity .55s ease;
}

body.playing #ui { opacity: 1; }

/* ============ HUD ============ */

.topbar {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  left: max(20px, env(safe-area-inset-left));
  right: max(20px, env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.hud-panel {
  position: relative;
  background:
    linear-gradient(135deg, rgba(123, 255, 143, 0.045), transparent 45%),
    var(--panel);
  border: 1px solid var(--line);
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.hud-panel::before {
  content: "";
  position: absolute;
  left: -1px;
  top: -1px;
  width: 18px;
  height: 18px;
  border-left: 2px solid var(--green);
  border-top: 2px solid var(--green);
  opacity: .8;
  pointer-events: none;
}

.health-panel {
  display: flex;
  gap: 13px;
  width: 330px;
  min-height: 86px;
  padding: 12px 16px 12px 12px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}

.portrait {
  flex: 0 0 58px;
  width: 58px;
  height: 58px;
  border: 1px solid rgba(125, 255, 90, .38);
  box-shadow: 0 0 20px rgba(125, 255, 90, .12);
  border-radius: 10px;
  overflow: hidden;
}
.portrait svg { width: 100%; height: 100%; display: block; }

.health-copy { flex: 1; min-width: 0; }

.hud-label {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #eaffdf;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.hud-label #hp-value {
  margin-left: auto;
  font-size: 18px;
  letter-spacing: .02em;
  color: #fff;
}
.dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--yellow);
  box-shadow: 0 0 8px var(--yellow);
}
.dot.green { background: var(--green); box-shadow: 0 0 9px var(--green); }

.bar {
  position: relative;
  height: 10px;
  margin-top: 8px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.07);
  transform: skewX(-12deg);
}
.bar i, .bar b {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  transition: transform .16s ease;
}
.hp-bar i {
  background: linear-gradient(90deg, #49db78, #a5ff6b 55%, #e8ffa6);
  box-shadow: 0 0 18px rgba(125, 255, 90, .45);
  z-index: 2;
}
.hp-bar b {
  background: #ff8d5e;
  z-index: 1;
  transition: transform .65s cubic-bezier(.2, .7, .3, 1);
}
.energy-bar { height: 8px; margin-top: 7px; }
.energy-bar i {
  background: linear-gradient(90deg, #3f9a76, #6affd0 50%, #b5ffec);
  box-shadow: 0 0 14px rgba(83, 255, 204, .36);
}

.tiny-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 5px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  white-space: nowrap;
}
#dash-status.ready { color: var(--green); }

.wave-panel {
  padding: 9px 24px 10px;
  min-width: 250px;
  text-align: center;
  clip-path: polygon(18px 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%, 0 18px);
}
.eyebrow {
  display: block;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
}
#wave-title {
  margin-top: 1px;
  font-family: var(--font-display);
  font-size: 31px;
  letter-spacing: .075em;
  line-height: 1;
  color: #f4ffe9;
  text-shadow: 0 0 22px rgba(125, 255, 90, .35);
}
.wave-meta {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 4px;
  color: #9fbdac;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .16em;
}
.wave-meta .separator { color: rgba(125, 255, 90, .45); }

.score-panel {
  display: flex;
  align-items: stretch;
  min-width: 284px;
  padding: 12px 14px;
  gap: 18px;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 18px 100%, 0 calc(100% - 18px));
}
.score-block { min-width: 86px; }
.score-block strong {
  display: block;
  margin-top: 2px;
  font-family: var(--font-display);
  font-size: 27px;
  font-weight: 400;
  letter-spacing: .08em;
  color: #f5ffe9;
  line-height: 1;
}
.score-block.seeds strong { color: var(--yellow); text-shadow: 0 0 18px rgba(245, 211, 63, .3); }
.combo-chip {
  align-self: center;
  margin-left: auto;
  padding: 5px 8px 4px;
  border: 1px solid rgba(245, 211, 63, .22);
  background: rgba(245, 211, 63, .06);
  color: var(--yellow);
  text-align: center;
  transform: skewX(-7deg);
  opacity: .42;
  transition: opacity .2s, transform .2s;
}
.combo-chip.active { opacity: 1; transform: skewX(-7deg) scale(1.05); box-shadow: 0 0 18px rgba(245, 211, 63, .14); }
.combo-chip span { display: block; font-size: 7px; letter-spacing: .16em; }
.combo-chip b { font-family: var(--font-display); font-weight: 400; font-size: 22px; line-height: .9; }

.minimap-wrap {
  position: absolute;
  top: 116px;
  right: max(20px, env(safe-area-inset-right));
  width: 156px;
  height: 156px;
  border-radius: 50%;
  padding: 6px;
  background: rgba(5, 15, 11, .68);
  border: 1px solid rgba(125, 255, 90, .22);
  box-shadow: 0 0 0 5px rgba(4, 12, 9, .28), inset 0 0 30px rgba(0, 0, 0, .5);
}
.minimap-wrap::before { display: none; }
#minimap { width: 100%; height: 100%; display: block; border-radius: 50%; }
.minimap-label {
  position: absolute;
  bottom: -15px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .25em;
}
.radar-sweep {
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  background: conic-gradient(from 0deg, transparent 0 330deg, rgba(125, 255, 90, .12) 355deg, rgba(125, 255, 90, .28) 360deg);
  animation: sweep 4s linear infinite;
  pointer-events: none;
  mix-blend-mode: screen;
}
@keyframes sweep { to { transform: rotate(360deg); } }

/* ============ crosshair ============ */
#crosshair {
  position: absolute;
  left: 0;
  top: 0;
  width: 40px;
  height: 40px;
  margin: -20px 0 0 -20px;
  opacity: 0;
  transition: opacity .2s;
  will-change: transform;
}
body.playing #crosshair { opacity: 1; }
.ch-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 4px;
  margin: -2px;
  background: #eaffdd;
  border-radius: 50%;
  box-shadow: 0 0 8px var(--green);
}
.ch {
  position: absolute;
  background: rgba(236, 255, 224, .85);
  box-shadow: 0 0 5px rgba(125, 255, 90, .8);
  transition: transform .12s ease;
}
.ch-t, .ch-b { left: 50%; width: 1px; height: 8px; margin-left: -.5px; }
.ch-l, .ch-r { top: 50%; height: 1px; width: 8px; margin-top: -.5px; }
.ch-t { top: 3px; } .ch-b { bottom: 3px; } .ch-l { left: 3px; } .ch-r { right: 3px; }
.ch-ring {
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(125, 255, 90, .25);
  border-radius: 50%;
  transition: transform .1s;
}
body.firing #crosshair .ch-t { transform: translateY(-3px); }
body.firing #crosshair .ch-b { transform: translateY(3px); }
body.firing #crosshair .ch-l { transform: translateX(-3px); }
body.firing #crosshair .ch-r { transform: translateX(3px); }
body.firing #crosshair .ch-ring { transform: scale(1.22); border-color: rgba(125, 255, 90, .55); }

#hitmarker {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 26px;
  height: 26px;
  margin: -13px;
  opacity: 0;
  transform: rotate(45deg) scale(.6);
  background:
    linear-gradient(45deg, transparent 46%, #fff 46% 54%, transparent 54%) center/100% 100% no-repeat,
    linear-gradient(-45deg, transparent 46%, #fff 46% 54%, transparent 54%) center/100% 100% no-repeat;
  filter: drop-shadow(0 0 4px rgba(125, 255, 90, .9));
}
#hitmarker.show { animation: hit .22s ease-out; }
#hitmarker.kill { filter: drop-shadow(0 0 7px #ff5c6c); }
@keyframes hit {
  0% { opacity: 1; transform: rotate(45deg) scale(.55); }
  55% { opacity: 1; transform: rotate(45deg) scale(1.15); }
  100% { opacity: 0; transform: rotate(45deg) scale(1.35); }
}

/* ============ overlays ============ */
#damage-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 40%, rgba(255, 22, 46, .35) 100%),
    linear-gradient(90deg, rgba(255, 25, 45, .15), transparent 15%, transparent 85%, rgba(255, 25, 45, .15));
  transition: opacity .3s ease;
  mix-blend-mode: screen;
}
#scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .13;
  background: repeating-linear-gradient(0deg, transparent 0 2px, rgba(4, 14, 10, .55) 3px);
  mix-blend-mode: multiply;
}

.gun-panel {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(22px, env(safe-area-inset-bottom));
  width: 300px;
  padding: 11px 14px 10px;
  display: flex;
  gap: 11px;
  align-items: center;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 0 100%);
}
.gun-icon {
  width: 62px;
  height: 44px;
  flex: 0 0 62px;
  border-right: 1px solid var(--line);
  padding-right: 10px;
}
.gun-icon svg { width: 100%; height: 100%; filter: drop-shadow(0 0 8px rgba(125, 255, 90, .18)); }
.gun-copy { flex: 1; min-width: 0; }

.bottom-right {
  position: absolute;
  right: max(20px, env(safe-area-inset-right));
  bottom: max(22px, env(safe-area-inset-bottom));
  display: flex;
  gap: 8px;
  pointer-events: auto;
}
.icon-btn {
  width: 39px;
  height: 39px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: #bcd5c6;
  font-size: 15px;
  cursor: pointer;
  transition: all .18s;
  backdrop-filter: blur(10px);
}
.icon-btn:hover { color: var(--green); border-color: var(--line-hot); background: rgba(20, 52, 39, .86); }
.icon-btn.off { color: #62786c; text-decoration: line-through; }

.bossbar {
  position: absolute;
  top: 108px;
  left: 50%;
  width: min(510px, 52vw);
  transform: translateX(-50%) translateY(-8px);
  opacity: 0;
  transition: opacity .35s, transform .35s;
  pointer-events: none;
}
.bossbar.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.boss-copy { display: flex; justify-content: space-between; align-items: baseline; padding: 0 2px 5px; }
.boss-copy span { font-size: 8px; font-weight: 700; letter-spacing: .25em; color: var(--red); }
.boss-copy b { font-family: var(--font-display); font-weight: 400; letter-spacing: .1em; font-size: 22px; color: #ffe9e9; text-shadow: 0 0 20px rgba(255, 50, 70, .5); }
.bossbar .bar { height: 8px; border-color: rgba(255, 92, 108, .18); background: rgba(50, 0, 5, .55); }
.bossbar .bar i { background: linear-gradient(90deg, #8b1022, #ff3b51 55%, #ffb0a8); box-shadow: 0 0 18px rgba(255, 59, 81, .5); }

.wave-banner {
  position: absolute;
  left: 50%;
  top: 28%;
  min-width: 420px;
  padding: 15px 60px 17px;
  text-align: center;
  opacity: 0;
  transform: translate(-50%, 16px) scale(.96);
  transition: opacity .35s, transform .45s cubic-bezier(.2, .8, .2, 1);
  background: linear-gradient(90deg, transparent, rgba(4, 13, 10, .83) 18%, rgba(4, 13, 10, .83) 82%, transparent);
  border-top: 1px solid rgba(125, 255, 90, .35);
  border-bottom: 1px solid rgba(125, 255, 90, .35);
  pointer-events: none;
}
.wave-banner.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.wave-banner span { display: block; color: var(--green); font-size: 10px; font-weight: 700; letter-spacing: .38em; }
.wave-banner strong {
  display: block;
  font-family: var(--font-display);
  font-size: 60px;
  font-weight: 400;
  letter-spacing: .08em;
  line-height: .95;
  color: #f4ffe9;
  text-shadow: 0 0 35px rgba(125, 255, 90, .38);
}
.wave-banner em { display: block; margin-top: 4px; color: #94ae9f; font-style: normal; font-size: 11px; letter-spacing: .18em; text-transform: uppercase; }

.toast {
  position: absolute;
  left: 50%;
  bottom: 118px;
  transform: translate(-50%, 12px);
  padding: 7px 18px;
  color: var(--yellow);
  background: rgba(5, 15, 11, .78);
  border: 1px solid rgba(245, 211, 63, .2);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .18em;
  opacity: 0;
  transition: opacity .2s, transform .25s;
  pointer-events: none;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

.control-hint {
  position: absolute;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  display: flex;
  gap: 18px;
  color: #6d897b;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .14em;
  white-space: nowrap;
  opacity: .9;
  transition: opacity 1.2s;
}
.control-hint.fade { opacity: 0; }
kbd {
  display: inline-block;
  padding: 2px 5px;
  margin-right: 4px;
  border: 1px solid rgba(151, 190, 171, .3);
  border-bottom-color: rgba(151, 190, 171, .55);
  border-radius: 3px;
  background: rgba(10, 24, 18, .6);
  color: #c4dccd;
  font-family: var(--font-ui);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .04em;
}

/* ============ mobile controls ============ */
#mobile-controls { display: none; }
.joy-zone {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  bottom: max(34px, calc(env(safe-area-inset-bottom) + 12px));
  width: 122px;
  height: 122px;
  pointer-events: auto;
  touch-action: none;
}
.joy-base {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid rgba(125, 255, 90, .24);
  background: radial-gradient(circle, rgba(10, 29, 21, .65), rgba(6, 16, 12, .38));
  box-shadow: inset 0 0 25px rgba(0, 0, 0, .38);
}
.joy-ring { position: absolute; inset: 19px; border-radius: 50%; border: 1px dashed rgba(125, 255, 90, .22); }
.joy-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48px;
  height: 48px;
  margin: -24px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(195, 255, 180, .8), rgba(58, 132, 86, .68) 65%, rgba(9, 26, 18, .9));
  border: 1px solid rgba(160, 255, 167, .45);
