}
.mobile-btn.fire {
  position: relative;
  width: 92px;
  height: 92px;
  border-color: rgba(245, 211, 63, .48);
  box-shadow: 0 0 30px rgba(245, 211, 63, .1), inset 0 0 20px rgba(245, 211, 63, .05);
}
.mobile-btn.fire span { position: relative; z-index: 2; }
.mobile-btn.fire i {
  position: absolute;
  inset: 15px;
  border: 1px solid rgba(245, 211, 63, .16);
