}
.mobile-btn.fire.pressed { transform: scale(.94); background: radial-gradient(circle at 35% 30%, rgba(120, 91, 19, .8), rgba(25, 22, 8, .9)); }
.mobile-btn.dash {
  width: 58px;
  height: 58px;
  margin-bottom: 10px;
  border-color: rgba(108, 236, 255, .35);
  color: var(--cyan);
}
.mobile-btn.dash.cooldown { opacity: .38; }

/* ============ screens ============ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: none;
  opacity: 0;
  transition: opacity .45s ease;
  pointer-events: auto;
}
.screen.visible { display: flex; opacity: 1; }
.screen.leaving { opacity: 0; }

.title-screen {
  flex-direction: column;
  justify-content: space-between;
  padding: max(26px, env(safe-area-inset-top)) max(34px, env(safe-area-inset-right)) max(22px, env(safe-area-inset-bottom)) max(34px, env(safe-area-inset-left));
  background:
    radial-gradient(circle at 50% 48%, transparent 0 25%, rgba(3, 8, 6, .22) 48%, rgba(3, 8, 6, .78) 100%),
    linear-gradient(90deg, rgba(3, 8, 6, .86) 0%, rgba(3, 8, 6, .08) 35%, rgba(3, 8, 6, .08) 65%, rgba(3, 8, 6, .86) 100%);
}
.title-noise {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .3;
  background-image:
    radial-gradient(circle at 18% 20%, rgba(125, 255, 90, .12), transparent 22%),
    radial-gradient(circle at 82% 72%, rgba(108, 236, 255, .07), transparent 24%);
  mix-blend-mode: screen;
}
.title-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  z-index: 2;
}
.tagline {
  color: #9cbfa9;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .3em;
  text-transform: uppercase;
}
.sound-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 13px;
  border: 1px solid rgba(151, 195, 173, .22);
  background: rgba(4, 13, 10, .45);
  color: #a8c1b2;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .17em;
  cursor: pointer;
  backdrop-filter: blur(10px);
}
.sound-led { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }
.sound-pill.off .sound-led { background: #6b746e; box-shadow: none; }
.sound-pill.off { color: #6b746e; }

.title-lockup {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(740px, 90vw);
  transform: translate(-50%, -50%);
  text-align: center;
  z-index: 2;
}
.rick-and-morty {
  color: #d9f7df;
  font-family: var(--font-display);
  font-size: clamp(24px, 3.2vw, 42px);
  letter-spacing: .22em;
  line-height: 1;
  text-shadow: 0 0 28px rgba(125, 255, 90, .24);
}
.rick-and-morty span { color: var(--yellow); font-size: .7em; margin: 0 .2em; }
.title-lockup h1 {
  position: relative;
  margin: 4px 0 0;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(84px, 15vw, 190px);
  line-height: .76;
  letter-spacing: .03em;
  color: #f4ffe9;
  text-shadow:
    0 0 7px rgba(255, 255, 255, .28),
    0 0 45px rgba(125, 255, 90, .34),
    0 14px 60px rgba(0, 0, 0, .8);
  transform: rotate(-1.3deg);
}
.title-lockup h1 span {
  display: inline-block;
  color: var(--green);
  text-shadow:
    0 0 8px rgba(199, 255, 177, .65),
    0 0 35px rgba(125, 255, 90, .65),
    0 0 80px rgba(47, 255, 92, .28);
  letter-spacing: .05em;
}
.title-sub {
  margin: 24px auto 0;
  color: #b2c9ba;
  font-size: clamp(13px, 1.35vw, 17px);
  font-weight: 500;
  letter-spacing: .055em;
  line-height: 1.45;
}
.start-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 15px;
  margin-top: 27px;
  padding: 10px 22px 10px 12px;
  min-width: 280px;
  border: 1px solid rgba(141, 255, 124, .65);
  background: linear-gradient(110deg, rgba(38, 98, 53, .92), rgba(13, 43, 29, .94) 70%);
  color: #efffe9;
  cursor: pointer;
  text-align: left;
  box-shadow: 0 0 0 1px rgba(3, 8, 6, .65), 0 0 35px rgba(96, 255, 91, .15), inset 0 1px 0 rgba(255, 255, 255, .13);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
  transition: transform .18s, box-shadow .18s, background .18s;
}
.start-btn:hover {
  transform: translateY(-2px);
  background: linear-gradient(110deg, rgba(55, 137, 70, .98), rgba(17, 59, 39, .98) 70%);
  box-shadow: 0 0 0 1px rgba(3, 8, 6, .65), 0 0 50px rgba(96, 255, 91, .3), inset 0 1px 0 rgba(255, 255, 255, .2);
}
.start-btn:active { transform: translateY(0) scale(.985); }
.start-btn.small { min-width: 225px; margin-top: 0; }
.start-copy { display: flex; flex-direction: column; gap: 1px; }
.start-copy b { font-size: 17px; font-weight: 700; letter-spacing: .16em; }
.start-copy small { color: #9fd6a6; font-size: 8px; font-weight: 700; letter-spacing: .22em; }
.start-arrow { margin-left: auto; font-size: 22px; color: var(--green); }
.portal-btn-icon {
  position: relative;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 2px solid var(--green);
  box-shadow: 0 0 18px rgba(125, 255, 90, .45), inset 0 0 18px rgba(125, 255, 90, .18);
}
.portal-btn-icon::before {
  content: "";
  position: absolute;
  inset: 7px;
  border-radius: 50%;
  border: 1px dashed rgba(215, 255, 195, .8);
  animation: spin 5s linear infinite;
}
.portal-btn-icon::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 11px;
  height: 11px;
  margin: -5.5px;
  border-radius: 50%;
  background: #d6ffbc;
  box-shadow: 0 0 15px #8dff68;
}
@keyframes spin { to { transform: rotate(360deg); } }
.best-line {
  margin-top: 18px;
  color: #6c8878;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .2em;
}
.best-line b { color: var(--yellow); font-size: 12px; letter-spacing: .12em; margin-left: 4px; }

.title-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  color: #6c8878;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .12em;
}
.controls-grid { display: flex; gap: 18px; }
.controls-grid span { display: flex; align-items: center; }
.disclaimer { max-width: 300px; text-align: right; opacity: .65; }

/* pause + end */
.pause-screen, .end-screen {
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle, rgba(7, 18, 13, .7), rgba(2, 6, 4, .92));
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
}
.modal {
  position: relative;
  width: min(540px, calc(100vw - 40px));
  padding: 34px 38px 30px;
  text-align: center;
  background: linear-gradient(145deg, rgba(19, 46, 34, .92), rgba(5, 14, 10, .96));
  border: 1px solid rgba(125, 255, 90, .26);
  box-shadow: 0 30px 90px rgba(0, 0, 0, .6), inset 0 1px 0 rgba(255, 255, 255, .06);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
}
.modal::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -1px;
  width: 42%;
  height: 1px;
  transform: translateX(-50%);
  background: var(--green);
  box-shadow: 0 0 22px var(--green);
}
.modal-kicker { color: var(--green); font-size: 9px; font-weight: 700; letter-spacing: .32em; }
.modal h2 {
  margin: 8px 0 4px;
  font-family: var(--font-display);
  font-size: 70px;
  font-weight: 400;
  line-height: .9;
  letter-spacing: .06em;
  color: #f2ffe8;
  text-shadow: 0 0 36px rgba(125, 255, 90, .3);
}
.modal p { margin: 14px 0 0; color: #9bb4a4; font-size: 13px; letter-spacing: .05em; }
.modal-actions { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 26px; flex-wrap: wrap; }
.ghost-btn {
  padding: 15px 20px;
  border: 1px solid rgba(151, 195, 173, .22);
  background: rgba(5, 16, 11, .5);
  color: #8da89a;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .18em;
  cursor: pointer;
  transition: all .2s;
}
.ghost-btn:hover { color: var(--yellow); border-color: rgba(245, 211, 63, .38); }
.modal-hint { margin-top: 22px; color: #678174; font-size: 9px; font-weight: 600; letter-spacing: .13em; }
.end-modal { width: min(590px, calc(100vw - 40px)); }
.end-screen.win .modal { border-color: rgba(245, 211, 63, .45); }
.end-screen.win .modal::before { background: var(--yellow); box-shadow: 0 0 25px var(--yellow); }
.end-screen.win .modal-kicker { color: var(--yellow); }
.end-screen.win .modal h2 { color: var(--yellow); text-shadow: 0 0 40px rgba(245, 211, 63, .35); }
.end-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin-top: 26px;
  background: rgba(125, 255, 90, .12);
  border: 1px solid rgba(125, 255, 90, .12);
}
.end-stats div { padding: 13px 8px 11px; background: rgba(5, 16, 11, .76); }
.end-stats span { display: block; color: #6c8878; font-size: 8px; font-weight: 700; letter-spacing: .19em; }
.end-stats b { display: block; margin-top: 3px; font-family: var(--font-display); font-weight: 400; font-size: 29px; letter-spacing: .08em; color: #edffe3; }

.loading-screen {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: center;
