    [-0.3, 0.18, -0.03, 0.1], [0.29, 0.2, -0.04, 0.1], [-0.1, 0.28, -0.2, 0.11],
    [0.12, 0.26, -0.22, 0.1],
  ];
  tuftPositions.forEach(([x, y, z, r], i) => {
