    addCyl(pivot, 0.077, 0.07, 0.36, 8, skin, 0, -0.31, 0);
    addSphere(pivot, 0.092, skin, 0, -0.52, 0, 1, 1.1, 0.9);
    pivot.rotation.z = side * 0.08;
