  root.scale.setScalar(scale);
  root.userData = {
    visual, legL, legR, armL, armR, head, gun, core, muzzle, muzzleGlow, ring, mats: [],
    walk: 0, recoil: 0, flash: 0,
  };
  markShadows(visual);
  gunGlow.userData.noShadow = muzzleGlow.userData.noShadow = ring.userData.noShadow = true;
  return root;
}

