+    vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
+    fragmentShader: `
+      uniform float uTime;
+      varying vec2 vUv;
+      void main(){
+        vec2 p=vUv-0.5; float r=length(p)*2.0; float a=atan(p.y,p.x);
+        float sw=sin(a*5.0+r*13.0-uTime*4.0)*0.5+0.5;
+        float sw2=sin(a*-4.0+r*20.0+uTime*2.2)*0.5+0.5;
+        float edge=smoothstep(1.0,0.72,r);
+        vec3 col=mix(vec3(0.02,0.3,0.07),vec3(0.6,2.0,0.45),sw*0.85+sw2*0.25);
+        col=mix(col,vec3(1.4,2.3,1.1),pow(smoothstep(1.0,0.0,r),7.0));
+        gl_FragColor=vec4(col,edge*(0.7+0.25*sin(uTime*3.0+r*7.0)));
+      }
+    `,
+  });
+}
