#damage-numbers {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.damage-number {
  position: absolute;
  transform: translate(-50%, -50%);
  color: #eaffdf;
  font-family: var(--font-display);
  font-size: 22px;
  letter-spacing: .05em;
  text-shadow: 0 0 9px rgba(125, 255, 90, .55), 0 2px 2px rgba(0, 0, 0, .7);
  animation: float-dmg .8s ease-out forwards;
  will-change: transform, opacity;
  white-space: nowrap;
}
.damage-number.score {
  color: var(--yellow);
  font-size: 27px;
  text-shadow: 0 0 12px rgba(245, 211, 63, .6), 0 2px 2px rgba(0, 0, 0, .7);
}
@keyframes float-dmg {
  0% { opacity: 0; transform: translate(-50%, -35%) scale(.7); }
  18% { opacity: 1; transform: translate(-50%, -60%) scale(1.06); }
  100% { opacity: 0; transform: translate(-50%, -170%) scale(.92); }
}

