    if (p.spawned && p.age > p.duration) {
      scene.remove(p.group);
      p.group.traverse((o) => {
        if (o.geometry) o.geometry.dispose?.();
        if (o.material && o.material !== p.mat) o.material.dispose?.();
      });
      portals.splice(i, 1);
    }
  }
